import { canonicalHost } from "./credentials-BTv2IfUZ.js";
import { CliError } from "./client-sMzq2PWG.js";
import { resolveClient, withErrorHandling } from "./_lifecycle-shared-_9BzQ9Y2.js";
import { readExecutaIdentity } from "./executa-cache-BFoUtb4J.js";
import { addTrustedPublisher, listTrustedPublishers, removeTrustedPublisher } from "./binary-upload-DVhQ0uY0.js";
import { resolve } from "node:path";
import { bold, cyan, dim, green } from "kleur/colors";

//#region src/commands/executa-trusted-publisher.ts
function resolveToolId(opts, host) {
	if (opts.toolId) return opts.toolId;
	const dir = resolve(opts.dir ?? process.cwd());
	const identity = readExecutaIdentity(dir);
	if (!identity) throw new CliError(`no .anna/executa.json identity cache in ${dir} — run \`anna-app executa publish\` / \`anna-app apps push\` once, or pass --tool-id`, 4);
	if (identity.host !== canonicalHost(host)) throw new CliError(`identity cache in ${dir} belongs to ${identity.host}, but the current PAT targets ${canonicalHost(host)} — use --account or pass --tool-id`, 4);
	return identity.tool_id;
}
function setup(opts) {
	const { client, host } = resolveClient({
		account: opts.account,
		fetchImpl: opts.fetchImpl
	});
	return {
		client,
		host,
		toolId: resolveToolId(opts, host)
	};
}
function printPublisher(p) {
	console.log(`  #${p.id} ${bold(p.repository)} ${cyan(p.workflow)}` + (p.environment ? dim(` env=${p.environment}`) : dim(" env=(any)")) + (p.last_used_at ? dim(` last used ${p.last_used_at}`) : dim(" never used")));
}
async function runTrustedPublisherAdd(opts) {
	return withErrorHandling(async () => {
		if (!/^[^/\s]+\/[^/\s]+$/.test(opts.repository)) throw new CliError(`--repository must be "owner/repo" (got "${opts.repository}")`, 2);
		const { client, toolId } = setup(opts);
		const created = await addTrustedPublisher(client, toolId, {
			repository: opts.repository,
			workflow: opts.workflow,
			environment: opts.environment
		});
		if (opts.json) {
			console.log(JSON.stringify({
				tool_id: toolId,
				trusted_publisher: created
			}, null, 2));
			return 0;
		}
		console.log(green(`✓ trusted publisher registered for ${toolId}:`));
		printPublisher(created);
		console.log(dim("→ that workflow can now run ") + cyan("anna-app executa upload-binaries --oidc") + dim(" with `permissions: id-token: write` and no PAT"));
		return 0;
	});
}
async function runTrustedPublisherList(opts) {
	return withErrorHandling(async () => {
		const { client, toolId } = setup(opts);
		const rows = await listTrustedPublishers(client, toolId);
		if (opts.json) {
			console.log(JSON.stringify({
				tool_id: toolId,
				trusted_publishers: rows
			}, null, 2));
			return 0;
		}
		if (rows.length === 0) {
			console.log(dim(`(no trusted publishers registered for ${toolId})`));
			return 0;
		}
		console.log(bold(`trusted publishers for ${toolId}:`));
		for (const p of rows) printPublisher(p);
		return 0;
	});
}
async function runTrustedPublisherRemove(opts) {
	return withErrorHandling(async () => {
		const { client, toolId } = setup(opts);
		await removeTrustedPublisher(client, toolId, opts.publisherId);
		if (opts.json) {
			console.log(JSON.stringify({
				tool_id: toolId,
				removed: opts.publisherId
			}, null, 2));
			return 0;
		}
		console.log(green(`✓ removed trusted publisher #${opts.publisherId} from ${toolId}`));
		return 0;
	});
}

//#endregion
export { runTrustedPublisherAdd, runTrustedPublisherList, runTrustedPublisherRemove };